class Solution:
    def maxPointsInsideSquare(self, points: List[List[int]], s: str) -> int:
        idx = sorted(range(len(points)), key=lambda i: max(abs(points[i][0]), abs(points[i][1])))
        seen = [False] * 26
        cnt = 0
        for i in idx:
            c = ord(s[i]) - 97
            if seen[c]:
                break
            seen[c] = True
            cnt += 1
        return cnt

