class Solution {
public:
    int maxPointsInsideSquare(vector<vector<int>>& points, string s) {
        int n = points.size();
        vector<int> idx(n);
        iota(idx.begin(), idx.end(), 0);
        sort(idx.begin(), idx.end(), [&](int a, int b) {
            long long ra = max(abs(points[a][0]), abs(points[a][1]));
            long long rb = max(abs(points[b][0]), abs(points[b][1]));
            return ra < rb;
        });
        bool seen[26] = {false};
        int cnt = 0;
        for (int i : idx) {
            int c = s[i] - 'a';
            if (seen[c]) break;
            seen[c] = true;
            cnt++;
        }
        return cnt;
    }
};

