class Solution {
    public int maxPointsInsideSquare(int[][] points, String s) {
        int n = points.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> Long.compare(
            Math.max(Math.abs(points[a][0]), Math.abs(points[a][1])),
            Math.max(Math.abs(points[b][0]), Math.abs(points[b][1]))));
        boolean[] seen = new boolean[26];
        int cnt = 0;
        for (int i : idx) {
            int c = s.charAt(i) - 'a';
            if (seen[c]) break;
            seen[c] = true;
            cnt++;
        }
        return cnt;
    }
}

