class Solution:
    def maxPointsInsideSquare(self, points: List[List[int]], s: str) -> int:
        INF = float('inf')
        min1 = [INF] * 26
        min2 = [INF] * 26
        for (x, y), c in zip(points, s):
            r = max(abs(x), abs(y))
            j = ord(c) - 97
            if r < min1[j]:
                min2[j] = min1[j]
                min1[j] = r
            elif r < min2[j]:
                min2[j] = r
        limit = min(min2)
        return sum(max(abs(x), abs(y)) < limit for x, y in points)

