class Solution {
    public int maxPointsInsideSquare(int[][] points, String s) {
        long INF = Long.MAX_VALUE;
        long[] mn1 = new long[26], mn2 = new long[26];
        Arrays.fill(mn1, INF);
        Arrays.fill(mn2, INF);
        for (int i = 0; i < points.length; i++) {
            long r = Math.max(Math.abs(points[i][0]), Math.abs(points[i][1]));
            int j = s.charAt(i) - 'a';
            if (r < mn1[j]) { mn2[j] = mn1[j]; mn1[j] = r; }
            else if (r < mn2[j]) mn2[j] = r;
        }
        long limit = INF;
        for (long v : mn2) limit = Math.min(limit, v);
        int cnt = 0;
        for (int[] p : points)
            if (Math.max(Math.abs(p[0]), Math.abs(p[1])) < limit) cnt++;
        return cnt;
    }
}

